SELECT DISTINCT db.display_name
FROM bank_dwh.dim_branch db
WHERE db.is_current = TRUE
  AND db.is_active = TRUE;

TRUNCATE TABLE bank_dwh.fact_aml_alert;

SELECT DISTINCT b.display_name
FROM bank_dwh.dim_branch b
INNER JOIN bank_dwh.fact_aml_alert a ON b.branch_key = a.branch_key
WHERE b.is_current = TRUE
  AND b.is_active = TRUE;

TRUNCATE TABLE bank_dwh.fact_aml_alert;

SELECT DISTINCT b.display_name AS branch_name
FROM bank_dwh.dim_branch b
INNER JOIN bank_dwh.fact_aml_alert a ON b.branch_key = a.branch_key
WHERE b.is_current = TRUE AND b.is_active = TRUE;

TRUNCATE TABLE bank_dwh.fact_aml_alert;
